using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
namespace ForgottenVillage.Editor {
[InitializeOnLoad] public static class PlaneDreamChecks {
 static Keyboard testKeyboard;static InputSettings.BackgroundBehavior previousBackground;static Key[] heldKeys=System.Array.Empty<Key>();static IEnumerator routine;static int frame;static StringBuilder report;static readonly List<string> errors=new List<string>();
 static PlaneDreamChecks(){EditorApplication.update+=Tick;Application.logMessageReceived+=(m,s,t)=>{if(SessionState.GetBool("PLANE_TEST_ACTIVE",false)&&(t==LogType.Error||t==LogType.Exception||t==LogType.Assert))errors.Add(m);};}
 [MenuItem("Forgotten Village/Test Alchemist plane dream")]
 public static void Request(){EditorSceneManager.OpenScene("Assets/Scenes/rpgpp_lt_scene_1.0.unity");SessionState.SetBool("PLANE_TEST_PENDING",true);EditorApplication.isPlaying=true;}
 static void Tick(){if(!EditorApplication.isPlaying||EditorApplication.isCompiling)return;if(SessionState.GetBool("PLANE_TEST_PENDING",false)&&Time.frameCount>12){SessionState.SetBool("PLANE_TEST_PENDING",false);SessionState.SetBool("PLANE_TEST_ACTIVE",true);errors.Clear();report=new StringBuilder();routine=Run();}if(routine==null||frame==Time.frameCount)return;frame=Time.frameCount;try{if(!routine.MoveNext())Finish(null);}catch(Exception e){Finish(e);}}
 static void Finish(Exception failure){if(testKeyboard!=null){InputSystem.RemoveDevice(testKeyboard);testKeyboard=null;InputSystem.settings.backgroundBehavior=previousBackground;}if(Keyboard.current!=null)InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());report.AppendLine(failure==null?"PASS: Plane dream Play Mode suite completed":"FAIL: "+failure);foreach(var error in errors)report.AppendLine("Runtime error: "+error);report.AppendLine("Scope: real Unity frames, physics, UI callbacks and injected desktop input; full 60 active seconds with editor-only route following. No physical Meta Quest testing.");File.WriteAllText("Verification/plane-dream-playmode.txt",report.ToString());routine=null;VillageStorage.overridePath=null;SessionState.SetBool("PLANE_TEST_ACTIVE",false);EditorApplication.isPlaying=false;}
 static void Check(bool value,string message){if(!value)throw new Exception(message);report.AppendLine("PASS: "+message);File.WriteAllText("Verification/plane-dream-progress.txt",report.ToString());}
 static IEnumerable<object> Wait(float seconds){double end=Time.realtimeSinceStartupAsDouble+seconds;while(Time.realtimeSinceStartupAsDouble<end)yield return null;}
 static IEnumerable<object> ActiveFor(PlaneDreamRun r,double seconds){double end=r.state.elapsed+seconds,timeout=Time.realtimeSinceStartupAsDouble+10;while(r.state.elapsed<end){if(r.state.phase!=PlaneRunState.Phase.Flying||Time.realtimeSinceStartupAsDouble>timeout)throw new Exception("Flight interrupted during input check: "+r.state.phase);yield return null;}}
 static IEnumerable<object> Launched(PlaneDreamRun r){double end=Time.realtimeSinceStartupAsDouble+15;while(r.state.phase==PlaneRunState.Phase.Countdown||(r.state.phase==PlaneRunState.Phase.Flying&&r.DistanceTravelled==0)){if(Time.realtimeSinceStartupAsDouble>end)throw new Exception("Countdown stalled: "+r.state.phase+"; "+r.input.Status);yield return null;}}
 static IEnumerable<object> Transition(VillageGame g){float end=Time.realtimeSinceStartup+30;while(g.transitions.Busy){if(Time.realtimeSinceStartup>end)throw new Exception("Transition timed out");yield return null;}yield return null;}
 static void Button(VillageGame g,string name){g.ui.buttons.GetComponentsInChildren<UnityEngine.UI.Button>().First(b=>b.gameObject.activeSelf&&b.name==name).onClick.Invoke();}
 static void Keys(params Key[] keys){heldKeys=keys;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(keys));}
 public static Vector2 SafeCommand(PlaneDreamRun r){var next=r.obstacles.Next();if(!next)return Vector2.zero;return new Vector2(next.Pattern.safeTarget.x/r.tuning.halfWidth,(next.Pattern.safeTarget.y-r.tuning.normalHeight)/r.tuning.verticalRange);}
 // Reused by the existing six-house/Elder regression suite, preserving real completion requirements.
 public static IEnumerable<object> CompleteAlchemist(VillageGame g){
  var h=UnityEngine.Object.FindFirstObjectByType<AlchemistDreamHouse>();if(!h)throw new Exception("Missing Alchemist activity");if(!h.InDream){h.EnterDream();foreach(var x in Wait(.7f))yield return x;}
  var r=h.dream;r.AutomationInput=()=>SafeCommand(r);r.Begin();double deadline=Time.realtimeSinceStartupAsDouble+150;bool captured=false;
  while(h.InDream){if(!captured&&r.state.elapsed>=10){VillageAutomation.Capture(g,"plane-dream-play-preview");captured=true;}if(r.state.phase==PlaneRunState.Phase.Failed)throw new Exception("Route follower crashed: "+r.state.elapsed+"s");if(Time.realtimeSinceStartupAsDouble>deadline)throw new Exception("Survival/return timed out: "+r.state.phase);yield return null;}
  r.AutomationInput=null;if(!g.state.alchemistDreamWon||r.state.elapsed!=60)throw new Exception("Dream did not run for 60 active seconds");Button(g,"Show me the record");h.evidence.GetComponent<VillageInteractable>().Activate();if(!g.state.clues[1])throw new Exception("Clue #2 missing after evidence inspection");
 }
 static IEnumerator Run(){
  VillageStorage.overridePath=Path.GetFullPath("Verification/plane-dream-test-save.json");var g=UnityEngine.Object.FindFirstObjectByType<VillageGame>();Check(g&&g.transitions,"Existing village and transition service loaded");g.NewGame();g.state.elder=true;g.ui.Close();g.Enter(1);foreach(var w in Transition(g))yield return w;
  var h=UnityEngine.Object.FindFirstObjectByType<AlchemistDreamHouse>();Check(h&&h.game==g,"Alchemist activity bound in existing house");Check(!UnityEngine.Object.FindFirstObjectByType<EngineeringStation>(),"Obsolete RC station removed");h.InspectEvidence();Check(!g.state.clues[1]&&!g.state.alchemistEvidenceInspected,"Evidence cannot be collected before dream victory");
  var resident=UnityEngine.Object.FindObjectsByType<VillageAction>(FindObjectsSortMode.None).First(a=>a.kind=="dialogue"&&a.index==1);resident.GetComponent<VillageInteractable>().Activate();Button(g,"Maybe later.");Check(!g.ui.IsOpen&&!h.InDream&&!g.state.puzzleSolved[1],"Maybe later closes safely without quest progress");resident.GetComponent<VillageInteractable>().Activate();Button(g,"I'll help you.");foreach(var w in Wait(.7f))yield return w;
  var r=h.dream;previousBackground=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;testKeyboard=InputSystem.AddDevice<Keyboard>();testKeyboard.MakeCurrent();r.input.AutomationBeforeCapture=()=>{testKeyboard.MakeCurrent();InputState.Change(testKeyboard,new KeyboardState(heldKeys),InputUpdateType.Dynamic);};Check(h.InDream&&r.gameObject.activeSelf&&g.ui.IsOpen,"Dialogue enters isolated dream and shows safety instructions");Check(UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Count(c=>c.enabled)==1,"No duplicate camera or XR view in dream");Check(r.aircraft.GetComponentsInChildren<MeshRenderer>().Length>0&&r.scenery.Length>=2,"PlaneRunner aircraft and valley assets loaded");
  Button(g,"Begin flight");Check(r.state.Remaining==60&&r.input.Ready,"Run begins with fresh timer and calibration");foreach(var w in Launched(r))yield return w;Check(r.state.phase==PlaneRunState.Phase.Flying&&r.DistanceTravelled>0,"Automatic forward flight starts after countdown: "+r.state.phase+" / distance "+r.DistanceTravelled);Check(r.obstacles.ActiveCount>0,"Random pooled obstacles spawn ahead of aircraft");var camera=g.player.View.transform.position;
  Keys(Key.D,Key.Space);foreach(var w in ActiveFor(r,.8))yield return w;Keys();Check(r.aircraft.Position.x>.3f&&r.aircraft.Position.y>r.tuning.normalHeight+.3f,"Desktop D and Space steer and raise airplane: "+r.aircraft.Position+" input "+r.input.Command);Check(Vector3.Distance(camera,g.player.View.transform.position)<.001f,"Aircraft motion does not move the viewing camera");
  g.ui.Pause();var elapsed=r.state.elapsed;var next=r.obstacles.Next();float z=next.Z;foreach(var w in Wait(.3f))yield return w;Check(r.state.elapsed==elapsed&&Mathf.Abs(next.Z-z)<.001f,"Pause freezes both survival time and obstacles");Button(g,"Recalibrate");Check(r.input.Ready,"Paused recalibration succeeds");Button(g,"Resume");Keys(Key.A,Key.LeftCtrl);foreach(var w in ActiveFor(r,1.3))yield return w;Keys();Check(r.aircraft.Position.x<-.3f&&r.aircraft.Position.y<r.tuning.normalHeight-.3f,"Desktop A and Ctrl steer and lower airplane: "+r.aircraft.Position+" input "+r.input.Command);
  r.Begin();foreach(var w in Launched(r))yield return w;r.obstacles.Clear();var obstacle=r.obstacles.Groups.First();obstacle.Place(PlanePatterns.Create(4,0,r.tuning),1.0f);foreach(var w in Wait(.45f))yield return w;Check(r.state.phase==PlaneRunState.Phase.Failed&&g.ui.heading.text=="Dream Failed","Actual approaching obstacle collision fails the run");elapsed=r.state.elapsed;foreach(var w in Wait(.2f))yield return w;Check(r.state.elapsed==elapsed,"Crash stops survival timer");Button(g,"Retry");Check(r.state.Remaining==60&&r.obstacles.ActiveCount==0&&r.aircraft.Position==new Vector3(0,r.tuning.normalHeight,0),"Retry clears obstacles, position and all elapsed time");
  foreach(var w in Wait(.1f))yield return w;VillageAutomation.Capture(g,"plane-dream-play-preview");double start=Time.realtimeSinceStartupAsDouble;
  foreach(var w in CompleteAlchemist(g))yield return w;
  Check(Time.realtimeSinceStartupAsDouble-start>=60,"Successful challenge used a full real-time minute, not a shortened test duration");Check(!h.InDream&&g.house==1&&!g.player.ActivityLocksMovement,"Success returns to Alchemist house and restores locomotion");Check(g.state.alchemistMemoryRecovered&&g.state.clues[1]&&g.state.inventory.Contains(VillageGame.Clues[1]),"Recovery dialogue and evidence inspection award existing Clue #2");Check(!g.state.Unlocked,"One clue cannot unlock Abandoned House");var saved=VillageStorage.Load();Check(saved.alchemistDreamWon&&saved.alchemistEvidenceInspected&&saved.clues[1],"Real JSON save preserves dream and clue completion");g.Exit();foreach(var w in Transition(g))yield return w;g.Enter(1);foreach(var w in Transition(g))yield return w;h=UnityEngine.Object.FindFirstObjectByType<AlchemistDreamHouse>();Check(h.evidence.activeSelf,"Re-entering house restores evidence availability");Check(errors.Count==0,"No runtime errors captured during Plane dream checks");
 }
}
}
